const descriptions={theme:['Настройки оформления SpaceClient: темы и палитра интерфейса','Твой стиль начинается здесь'],hands:['Настройки камеры и положения предметов в руке','Каждая деталь — на своём месте'],scene:['Главное меню SpaceClient с фиолетовыми световыми линиями','Знакомая игра. Другое настроение.'],hud:['Реальный игровой HUD SpaceClient','Всё важное перед глазами']};
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.gallery;const image=document.querySelector('#gallery-image');image.src=`assets/${key}.webp`;image.alt=descriptions[key][0];document.querySelector('#gallery-caption').textContent=`Реальный кадр клиента · ${button.querySelector('span').textContent}`;document.querySelectorAll('[data-gallery]').forEach(option=>{const chosen=option===button;option.classList.toggle('chosen',chosen);option.setAttribute('aria-pressed',String(chosen));});}));
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.view;const image=document.querySelector('#client-image');image.src=`assets/${key}.webp`;image.alt=descriptions[key][0];document.querySelector('#frame-caption').textContent=button.hasAttribute('data-pro')?'Pro Studio — оформление под тебя':descriptions[key][1];document.querySelectorAll('.image-tabs button').forEach(tab=>{const selected=tab.dataset.view===key;tab.classList.toggle('selected',selected);tab.setAttribute('aria-pressed',String(selected));});}));
